<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue';
import {getBearer,productImages,type ApiClient,type PublicProduct} from '@kuaixie/sdk';
import {productImageId} from './useProductPublishing';
const props=defineProps<{client:ApiClient;images?:unknown}>();const session=getBearer(),privateSources=ref<Record<string,string>>({}),failed=ref<Record<string,boolean>>({}),loading=ref<Record<string,boolean>>({}),attempted=new Set<string>(),urls=new Set<string>();let generation=0;
const images=computed(()=>productImages({id:'order-image',name:'',image_urls:props.images as PublicProduct['image_urls']}));
function source(path:string){return privateSources.value[path]||(productImageId(path)?props.client.files.publicUrl(path):path)}
async function fallback(path:string,retry=false){if(getBearer()!==session)return;if(retry)attempted.delete(path);if(attempted.has(path)){failed.value={...failed.value,[path]:true};return}const id=productImageId(path);if(!id){failed.value={...failed.value,[path]:true};return}attempted.add(path);loading.value={...loading.value,[path]:true};const current=generation;try{const bytes=await props.client.files.download(id);if(current!==generation||getBearer()!==session)return;const url=URL.createObjectURL(new Blob([bytes]));urls.add(url);const previous=privateSources.value[path];if(previous&&urls.has(previous)){URL.revokeObjectURL(previous);urls.delete(previous)}privateSources.value={...privateSources.value,[path]:url};failed.value={...failed.value,[path]:false}}catch{if(current===generation)failed.value={...failed.value,[path]:true}}finally{if(current===generation)loading.value={...loading.value,[path]:false}}}
function reset(){generation++;for(const url of urls)URL.revokeObjectURL(url);urls.clear();privateSources.value={};failed.value={};loading.value={};attempted.clear()}
watch(()=>props.images,reset);onBeforeUnmount(reset);
</script>
<template><section v-if="images.length" class="order-images"><h3>{{$t('productMedia.orderImages')}}</h3><p>{{$t('productMedia.orderImageHelp')}}</p><div class="images-grid"><figure v-for="(path,index) in images" :key="path"><img v-if="!failed[path]" :src="source(path)" :alt="$t('productMedia.imageAlt',{number:index+1})" @error="fallback(path)"/><p v-if="loading[path]">{{$t('account.loading')}}</p><template v-if="failed[path]"><p>{{$t('productMedia.orderImageUnavailable')}}</p><button type="button" @click="fallback(path,true)">{{$t('productMedia.preview')}}</button></template></figure></div></section></template>
<style scoped>.order-images{margin:18px 0}.order-images p{font-size:13px;line-height:1.6}.images-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:12px}.images-grid figure{margin:0;padding:8px;border:1px solid #cbd5e1;border-radius:8px}.images-grid img{width:100%;height:140px;object-fit:contain}.images-grid button{padding:8px}</style>
